   214→	err = s.validateBeaconBlock(ctx, blk, blockRoot)
   215→	if err != nil {
   216→		// If the parent is optimistic, process the block as usual
   217→		// This also does not penalize a peer which sends optimistic blocks
   218→		if !errors.Is(ErrOptimisticParent, err) {
   219→			log.WithError(err).WithFields(getBlockFields(blk)).Debug("Could not validate beacon block")
   220→			return pubsub.ValidationReject, err
   221→		}
   222→	}
   223→
   224→	// Record attribute of valid block.
   225→	span.SetAttributes(trace.Int64Attribute("slotInEpoch", int64(blk.Block().Slot()%params.BeaconConfig().SlotsPerEpoch)))
   226→	blkPb, err := blk.Proto()
   227→	if err != nil {
   228→		log.WithError(err).WithFields(getBlockFields(blk)).Debug("Could not convert beacon block to protobuf type")
   229→		return pubsub.ValidationIgnore, err
   230→	}
