   235→	startTime, err := slots.StartTime(genesisTime, blk.Block().Slot())
   236→	logFields := logrus.Fields{
   237→		"blockSlot":     blk.Block().Slot(),
   238→		"proposerIndex": blk.Block().ProposerIndex(),
   239→		"graffiti":      string(graffiti[:]),
   240→	}
